// Service worker for Two Seats. Generated by tools/build_site.py from
// tools/sw.template.js — edit the template, not _site/sw.js.
//
// Every asset except the page itself has a content-hashed name, so the
// strategy is simple: hashed files are served from the cache forever, and the
// page is fetched fresh when the network is there and from the cache when it
// is not. A new build has a new VERSION, which installs a fresh cache and
// deletes the old one.
const VERSION = "__VERSION__";
const CACHE = "two-seats-public-" + VERSION;
const PRECACHE = __PRECACHE__;

self.addEventListener("install", event => {
  event.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});

self.addEventListener("activate", event => {
  // Only this app's caches: the private copy at /twoseats/ shares the origin.
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith("two-seats-public-") && k !== CACHE).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener("fetch", event => {
  const req = event.request;
  if (req.method !== "GET") return;
  const url = new URL(req.url);
  // CDN libraries and the optional language model go straight to the network.
  if (url.origin !== self.location.origin) return;

  if (req.mode === "navigate") {
    event.respondWith(
      fetch(req)
        .then(res => {
          const copy = res.clone();
          caches.open(CACHE).then(c => c.put("./", copy));
          return res;
        })
        .catch(() => caches.match("./"))
    );
    return;
  }

  event.respondWith(
    caches.match(req).then(hit => hit || fetch(req).then(res => {
      if (res.ok) {
        const copy = res.clone();
        caches.open(CACHE).then(c => c.put(req, copy));
      }
      return res;
    }))
  );
});
